// Turns the vendored browser libraries into a TypeScript module.
//
// Why generate a file rather than read these at runtime: the Dockerfile
// copies dist/server.js and nothing else, so anything read from disk is
// missing in the image while working perfectly from the repo. And why
// not Vite's `?raw`: plain `node server.ts` - which is how this service
// runs locally and under `node --test` - cannot resolve it.
//
// A generated .ts is the one form both paths understand. It is checked
// in, and `npm run vendor` regenerates it after a version bump.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))

// The vendored libraries, plus this service's own browser scripts -
// which are plain .js rather than .ts because they run in a browser and
// are shipped verbatim, so there is nothing for tsc to check.
const files = [
  ['htmx.min.js', 'HTMX', here],
  ['idiomorph-ext.min.js', 'IDIOMORPH_EXT', here],
  ['page.js', 'PAGE_JS', join(here, '..', 'client')],
]

const parts = files.map(([name, key, dir]) => {
  const body = readFileSync(join(dir, name), 'utf8')
  return `export const ${key} = ${JSON.stringify(body)}\n`
})

writeFileSync(
  join(here, 'sources.ts'),
  '// GENERATED by vendor/build.mjs - do not edit. Run `npm run vendor`.\n' +
  '/* eslint-disable */\n' +
  parts.join('\n'),
)

console.log('wrote vendor/sources.ts')
